actions.script:
visible = false
info = null
isClient = !!ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')
if (!recordEntityName || !recordId) {
    if (requireVisible) ec.message.addError(ec.l10n.localize('No record given'))
    return
}
// checkOnly: a record the user may not see is recordVisible false, no error (an error would mark the read's transaction
// rollback-only); any other error is logged as not visible
ec.message.pushErrors()
let out = null
let why = null
try {
    out = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
            .parameters({recordEntityName: recordEntityName, recordId: recordId, checkOnly: true}).call()
    if (ec.message.hasError()) why = ec.message.getErrorsString()
    else if (out?.recordVisible !== true) why = out?.notVisibleReason || `${recordEntityName} ${recordId} not found`
    else if (forFiles && isClient && out.recordEntityName !== 'mantle.request.Request') why = `${recordEntityName} ${recordId} has no files for a client`
} catch (err) {
    why = err && err.message ? err.message : String(err)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (why) {
    ec.logger.warn(`Chatter: ${recordEntityName} ${recordId} is not visible to user ${ec.user.username}, nothing shown: ${why}`)
    if (requireVisible) ec.message.addError(why)
    return
}
info = out
info.recordId = recordId
visible = true
const entityName = info.recordEntityName
const value = ec.entity.find(entityName).condition(info.recordKeyField, recordId).one()
record = value ? value.getMap() : {}
if (entityName === 'mantle.work.effort.WorkEffort' && ['WepRouting','WepRoutingTask'].includes(record.purposeEnumId)) record = Object.fromEntries(['workEffortId','workEffortName','description','ownerPartyId','purposeEnumId','workEffortTypeEnumId'].map(k=>[k,record[k]]))
const L = (text) => ec.l10n.localize(text)
if (info.isParty) {
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', recordId).one()
    title = party ? (ec.resource.expand('PartyNameOnlyTemplate', '', party) || '').trim() : ''
    typeLabel = L(record.partyTypeEnumId === 'PtyOrganization' ? 'Organization' : 'Person')
} else if (entityName === 'moqui.resource.wiki.WikiPage') {
    // a wiki page by its title: the first heading of its text, else its name (the last part of its path)
    const path = String(record.pagePath || '')
    title = path ? path.substring(path.lastIndexOf('/') + 1) : ''
    ec.message.pushErrors()
    try {
        const page = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageInfoById').parameters({wikiPageId: recordId}).call()
        if (!path && page?.wikiSpace) title = page.wikiSpace.description || page.wikiSpace.wikiSpaceId || ''
        const text = page?.pageReference?.exists ? (page.pageReference.getText() ?? '') : ''
        const heading = String(text).match(/^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$/m)
        if (heading) title = heading[1].replace(/[*_`]/g, '').trim()
    } catch (err) {
        ec.logger.warn(`Chatter: the title of wiki page ${recordId} not read: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    typeLabel = L('Page')
} else if (entityName === 'mantle.humanres.employment.Employment') {
    // People's employment host (impl-people P2): the person and the employer, read after get#RecordLinkInfo admitted
    // the user as an HR reader of the employer
    const relationship = ec.entity.find('mantle.party.PartyRelationship').condition('partyRelationshipId', recordId).disableAuthz().one()
    const person = relationship ? ec.entity.find('mantle.party.Person').condition('partyId', relationship.fromPartyId).disableAuthz().one() : null
    const employer = relationship ? ec.entity.find('mantle.party.Organization').condition('partyId', relationship.toPartyId).disableAuthz().one() : null
    title = [[person?.firstName, person?.lastName].filter(Boolean).join(' '), employer?.organizationName].filter(Boolean).join(' at ')
    typeLabel = L('Employment')
} else if (entityName === 'mantle.humanres.ability.PartyQualification') {
    // People's qualification host (impl-people P18): the person and the kind, read after get#RecordLinkInfo admitted the
    // user as the person or an HR reader of an employer of theirs; never its number
    const person = ec.entity.find('mantle.party.Person').condition('partyId', record.partyId).disableAuthz().one()
    const kind = record.qualificationTypeEnumId ? ec.entity.find('moqui.basic.Enumeration').condition('enumId', record.qualificationTypeEnumId)
        .disableAuthz().one() : null
    title = [[person?.firstName, person?.lastName].filter(Boolean).join(' '), kind?.description].filter(Boolean).join(' · ')
    typeLabel = L('Qualification')
} else if (entityName === 'mantle.humanres.ability.PerformanceReview') {
    // People's review host (impl-people P20): the person and the cycle, read after get#RecordLinkInfo admitted the user as
    // its reviewer, a development reader of its employer or, once released, the person; never a rating or a note
    const person = ec.entity.find('mantle.party.Person').condition('partyId', record.partyId).disableAuthz().one()
    const cycle = ec.entity.find('mantle.humanres.ability.ReviewCycle').condition('reviewCycleId', record.reviewCycleId).disableAuthz().one()
    title = [[person?.firstName, person?.lastName].filter(Boolean).join(' '), cycle?.cycleName].filter(Boolean).join(' · ')
    typeLabel = L('Review')
} else if (entityName === 'mantle.sales.opportunity.SalesOpportunity') {
    // IronStone Sales' lead or opportunity (impl-sales P4): its name, read after get#RecordLinkInfo admitted the user as a
    // Sales reader of it; never its amount
    title = String(record.opportunityName || '')
    typeLabel = L(record.typeEnumId === 'SotLead' ? 'Lead' : 'Opportunity')
} else if (entityName === 'moqui.resource.GitMergeRequest') {
    // a merge request by its number and title (get#RecordLinkInfo checked its repository's view right)
    title = '!' + record.mergeRequestNum + ' ' + (record.title || '')
    typeLabel = L('Merge request')
} else {
    const nameFields = ['bomName', 'requestName', 'workEffortName', 'orderName', 'productName', 'categoryName', 'facilityName', 'assetName',
        'subject', 'shipmentId', 'description']
    const field = nameFields.find((name) => record[name])
    title = field ? String(record[field]) : ''
    const types = {'mantle.request.Request': 'Request', 'mantle.order.OrderHeader': 'Order', 'mantle.account.invoice.Invoice': 'Invoice',
        'mantle.account.payment.Payment': 'Payment', 'mantle.shipment.Shipment': 'Shipment', 'mantle.product.Product': 'Product',
        'mantle.product.bom.ProductBom': 'Bill of materials', 'mantle.facility.Facility': 'Facility', 'mantle.product.asset.Asset': 'Asset',
        'mantle.party.communication.CommunicationEvent': 'Message', 'mantle.party.agreement.Agreement': 'Agreement'}
    let type = types[entityName] || null
    // a goal is People's (impl-people P20; its readers alone see it), never a task
    if (entityName === 'mantle.work.effort.WorkEffort') type = {WetEvent: 'Event', WetProject: 'Project', WetSprint: 'Sprint', WetMilestone: 'Milestone',
            WetRelease: 'Release', WetGoal: 'Goal'}[record.workEffortTypeEnumId] || 'Task'
    typeLabel = type ? L(type) : info.recordTypeName
}
if (!title) title = String(recordId)
const link = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters({recordEntityName: entityName, id: recordId,
    workEffortTypeEnumId: record.workEffortTypeEnumId || null, partyTypeEnumId: record.partyTypeEnumId || null}).call()
url = link?.url || null
icon = link?.icon || 'sym_o_description'

const ids = []
const add = (id) => { const text = String(id || '').trim(); if (text && !ids.includes(text)) ids.push(text) }
if (Array.isArray(userIds)) userIds.forEach(add)
else if (userIds) String(userIds).split(',').forEach(add)
if (html) for (const match of String(html).matchAll(/data-mention-id="([^"]+)"/g)) add(match[1])
userIdList = []
partyIdList = []
nameList = []
if (ids.length === 0) return
for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', ids).disableAuthz().list()) {
    userIdList.push(account.userId)
    if (account.partyId && !partyIdList.includes(account.partyId)) partyIdList.push(account.partyId)
    nameList.push(account.userFullName || account.username)
}

const L = (text) => ec.l10n.localize(text)
const info = recordOut.info
const entityName = info.recordEntityName
const cf = ec.entity.conditionFactory
failedSources = []
followerList = []
myKinds = []
isFollowing = false
plannedActivities = []
fileList = []
fileCount = 0
hasContent = !!info.contentEntity
partyList = []
const part = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.error(`Chatter of ${entityName} ${recordId}: the ${name} part failed and is left out: ${err && err.message ? err.message : err}`)
        failedSources.push(name)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
const account = ec.user.userAccount
const myPartyId = account?.partyId || null
// the default due of a new activity: tomorrow at 09:00 in the user's time zone (a meeting until 09:30)
const tomorrowText = ec.l10n.format(new Date(Number(String(ec.user.nowTimestamp)) + 86400000), 'yyyy-MM-dd')
me = {userId: ec.user.userId, partyId: myPartyId, name: account?.userFullName || ec.user.username,
    defaultDue: tomorrowText + ' 09:00', defaultEnd: tomorrowText + ' 09:30'}
record = {entity: entityName, id: recordId, title: recordOut.title, typeLabel: recordOut.typeLabel, url: recordOut.url,
    icon: recordOut.icon, isParty: !!info.isParty, hasContent: hasContent, label: recordOut.typeLabel + ' ' + recordOut.title,
    // a message's subject: the record's name with its id (a party's name alone)
    subject: info.isParty || recordOut.title === String(recordId) ? recordOut.title : `${recordOut.title} (${recordId})`}
canMessage = ec.artifactExecution.isPermitted('mantle.party.communication.CommunicationEvent', 'AT_ENTITY', 'create')
canSchedule = ec.artifactExecution.isPermitted('mantle.work.effort.WorkEffort', 'AT_ENTITY', 'create')
mayUpdate = ec.artifactExecution.isPermitted(entityName, 'AT_ENTITY', 'update')

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const nowMillis = toMillis(ec.user.nowTimestamp)
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const today = fmt(nowMillis, 'yyyy-MM-dd')
const names = {}
const partyName = (partyId) => {
    if (!partyId) return null
    if (names[partyId] === undefined) {
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
        names[partyId] = party ? ((ec.resource.expand('PartyNameOnlyTemplate', '', party) || '').trim() || partyId) : null
    }
    return names[partyId]
}

// a client contact (impl-projects.md P10): no followers, files or parties of the record; it sends a message to the team
// and replies (ironstone.client.ClientServices, P10b), nothing else
forClient = !!recordOut.isClient
if (forClient) {
    canSchedule = false; mayUpdate = false
    canMessage = !!ec.service.sync().name('ironstone.client.ClientServices.get#ClientRecordWrites')
            .parameters({recordEntityName: entityName, recordId: recordId}).call()?.canMessage
}
// the followers, and the kinds each gets
if (!forClient) part('followers', () => {
    const out = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordFollowers')
            .parameters({recordEntityName: entityName, recordId: recordId}).call()
    if (ec.message.hasError()) return
    const kindNames = [['notifyMessages', 'messages'], ['notifyNotes', 'notes'], ['notifyActivities', 'activities'], ['notifyChanges', 'changes']]
    const followers = Array.from(out.followerList || [])
    const faces = ec.service.sync().name('ironstone.shared.ChatterServices.get#FaceImageParties').parameter('partyIdList',
            followers.map((follower) => follower.partyId)).call()?.partyIdList || []
    for (const follower of followers) {
        const kinds = kindNames.filter(([field]) => follower[field] === 'Y').map(([, kind]) => kind)
        followerList.push({userId: follower.userId, partyId: follower.partyId, name: follower.userFullName || follower.username || follower.userId,
            hasImage: !!follower.partyId && faces.includes(follower.partyId),
            kinds: kinds, kindsText: kinds.map((kind) => L(kind)).join(', '),
            canRemove: follower.userId === ec.user.userId || mayUpdate})
        if (follower.userId === ec.user.userId) myKinds = kinds
    }
    isFollowing = !!out.isFollowing
})

// the planned activities: the open ones of the timeline's activities source
part('activities', () => {
    const out = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordTimeline')
            .parameters({recordEntityName: entityName, recordId: recordId, kinds: ['activities'], pageSize: 1}).call()
    if (ec.message.hasError()) return
    for (const name of Array.from(out.failedSources || [])) failedSources.push(name)
    const purposes = {WepPhoneCall: ['sym_o_call', 'Call', 'call'], WepEmail: ['sym_o_mail', 'Email', 'email'],
        WepToDo: ['sym_o_checklist', 'To-do', 'todo'], WepMeeting: ['sym_o_groups', 'Meeting', 'meeting']}
    const tomorrow = fmt(nowMillis + 86400000, 'yyyy-MM-dd')
    const dueText = (millis) => {
        if (millis == null) return L('No due date')
        const day = fmt(millis, 'yyyy-MM-dd')
        const time = fmt(millis, 'HH:mm')
        const at = time === '00:00' ? '' : ' ' + time
        if (day === today) return L('Today') + at
        if (day === tomorrow) return L('Tomorrow') + at
        if (day === fmt(nowMillis - 86400000, 'yyyy-MM-dd')) return L('Yesterday') + at
        if (fmt(millis, 'yyyy') === fmt(nowMillis, 'yyyy')) return fmt(millis, 'EEE MMM d') + at
        return fmt(millis, 'yyyy-MM-dd') + at
    }
    for (const activity of Array.from(out.plannedActivities || [])) {
        const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', activity.workEffortId).one()
        if (row == null) continue
        const purpose = purposes[activity.purposeEnumId] || ['sym_o_task_alt', 'Activity', 'todo']
        const isMeeting = activity.purposeEnumId === 'WepMeeting'
        const dueMillis = toMillis(activity.dueDate)
        const endMillis = isMeeting ? toMillis(row.estimatedCompletionDate) : null
        const mine = !!myPartyId && (row.ownerPartyId === myPartyId || ec.entity.find('mantle.work.effort.WorkEffortParty')
                .condition('workEffortId', activity.workEffortId).condition('partyId', myPartyId).condition('roleTypeId', 'Assignee')
                .condition(cf.makeConditionDate('fromDate', 'thruDate', ec.user.nowTimestamp))
                .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).count() > 0)
        const link = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters({docType: 'MantleWorkEffort',
            id: activity.workEffortId, workEffortTypeEnumId: row.workEffortTypeEnumId}).call()
        const overdue = !!activity.overdue
        plannedActivities.push({workEffortId: activity.workEffortId, workEffortName: activity.workEffortName || activity.workEffortId,
            description: activity.description || null, purposeEnumId: activity.purposeEnumId, activityType: purpose[2],
            icon: purpose[0], typeLabel: L(purpose[1]), isMeeting: isMeeting, dueMillis: dueMillis, overdue: overdue,
            dueText: (overdue ? L('Overdue') + ' · ' : '') + dueText(dueMillis) + (endMillis != null ? '–' + fmt(endMillis, 'HH:mm') : ''),
            dueInput: dueMillis == null ? '' : fmt(dueMillis, 'yyyy-MM-dd HH:mm'), endInput: endMillis == null ? '' : fmt(endMillis, 'yyyy-MM-dd HH:mm'),
            assigneePartyId: activity.assigneePartyId || null, assigneeName: partyName(activity.assigneePartyId), url: link?.url || null,
            canUpdate: mine})
    }
})

// the attachments strip: the first files
if (hasContent && !(forClient && entityName !== 'mantle.request.Request')) part('files', () => {
    const out = ec.service.sync().name('ironstone.shared.RecordFilesServices.get#RecordFiles')
            .parameters({recordEntityName: entityName, recordId: recordId, limit: 6}).call()
    if (ec.message.hasError()) return
    fileList = Array.from(out.fileList || []).map((file) => ({contentKey: file.contentKey, fileName: file.fileName, icon: file.icon,
        isImage: file.isImage, isPdf: file.isPdf, hasFile: file.hasFile, sizeText: file.sizeText}))
    fileCount = out.fileCount || 0
})

// the record's parties with an email address, for Email… (Comms Compose)
if (!forClient) part('parties', () => {
    let partyIds = []
    const current = cf.makeConditionDate('fromDate', 'thruDate', ec.user.nowTimestamp)
    if (info.isParty) partyIds = [recordId]
    else if (entityName === 'mantle.request.Request') partyIds = Array.from(ec.entity.find('mantle.request.RequestParty')
            .condition('requestId', recordId).condition(current).list()).map((row) => row.partyId)
    else if (entityName === 'mantle.work.effort.WorkEffort') partyIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty')
            .condition('workEffortId', recordId).condition(current)
            .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).list()).map((row) => row.partyId)
    else if (entityName === 'mantle.order.OrderHeader') partyIds = Array.from(ec.entity.find('mantle.order.OrderPart')
            .condition('orderId', recordId).list()).flatMap((row) => [row.customerPartyId, row.vendorPartyId])
    else if (entityName === 'mantle.account.invoice.Invoice') partyIds = [record.fromPartyId, record.toPartyId]
    partyIds = Array.from(new Set(partyIds.filter((id) => id)))
    if (partyIds.length === 0) return
    const emails = {}
    for (const row of ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', 'in', partyIds)
            .condition('contactMechTypeEnumId', 'CmtEmailAddress').condition(current).orderBy('-fromDate').list()) {
        if (!row.infoString) continue
        if (!emails[row.partyId] || row.contactMechPurposeId === 'EmailPrimary') emails[row.partyId] = String(row.infoString)
    }
    for (const partyId of partyIds) {
        const name = partyName(partyId)
        if (name == null) continue
        partyList.push({partyId: partyId, name: name, email: emails[partyId] || null, isMe: partyId === myPartyId})
    }
})

const ids = Array.from(new Set(Array.from(partyIdList || []).filter((id) => id).map((id) => String(id))))
partyIdList = []
if (!ids.length) return
const found = new Set()
for (const row of ec.entity.find('mantle.party.PartyContent').condition('partyId', 'in', ids).condition('partyContentTypeEnumId', 'PcntFaceImage')
        .selectField('partyId').list()) found.add(row.partyId)
partyIdList = ids.filter((id) => found.has(id))

entryList = []
hasMore = false
nextBeforeDate = null
nextSeenKeys = []
failedSources = []
const L = (text) => ec.l10n.localize(text)
const info = recordOut.info
const entityName = info.recordEntityName
const kindValues = ['messages', 'notes', 'activities', 'changes', 'files']
const wanted = kinds && kindValues.includes(String(kinds)) ? [String(kinds)] : null
const beforeMillis = beforeDate != null && /^\d+$/.test(String(beforeDate)) ? Number(String(beforeDate)) : null
const seen = seenKeys == null ? [] : (Array.isArray(seenKeys) ? seenKeys : String(seenKeys).split(',')).map((key) => String(key).trim()).filter((key) => key)
const out = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordTimeline').parameters({recordEntityName: entityName,
    recordId: recordId, kinds: wanted, pageSize: pageSize || 25, beforeDate: beforeMillis == null ? null : new Date(beforeMillis),
    seenKeys: beforeMillis == null ? null : seen, chatRoomUrl: '/qapps/Comms/Chat'}).call()
if (ec.message.hasError()) return
hasMore = !!out.hasMore
nextSeenKeys = Array.from(out.nextSeenKeys || []).map((key) => String(key))
const sourceLabels = {communicationEvents: 'messages and notes', notes: 'notes', activities: 'activities', auditLog: 'changes',
    content: 'files', attachments: 'attachments', authors: 'authors', chatRoom: 'chat messages'}
failedSources = Array.from(out.failedSources || []).map((name) => L(sourceLabels[name] || name))

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const nowMillis = toMillis(ec.user.nowTimestamp)
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const today = fmt(nowMillis, 'yyyy-MM-dd')
const yesterday = fmt(nowMillis - 86400000, 'yyyy-MM-dd')
const whenText = (millis) => {
    if (millis == null) return ''
    const minutes = Math.floor((nowMillis - millis) / 60000)
    if (minutes >= 0 && minutes < 1) return L('Just now')
    if (minutes >= 0 && minutes < 60) return ec.resource.expand('${minutes} min ago', '', {minutes: minutes})
    const day = fmt(millis, 'yyyy-MM-dd')
    if (day === today) return L('Today') + ' ' + fmt(millis, 'HH:mm')
    if (day === yesterday) return L('Yesterday') + ' ' + fmt(millis, 'HH:mm')
    if (fmt(millis, 'yyyy') === fmt(nowMillis, 'yyyy')) return fmt(millis, 'MMM d HH:mm')
    return fmt(millis, 'yyyy-MM-dd')
}
const escapeHtml = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const textHtml = (text) => escapeHtml(String(text).replace(/\s+$/, '')).replace(/\r?\n/g, '<br>')
const plain = (html) => String(html).replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ')
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim()
const clean = (html) => {
    try {
        return ec.service.sync().name('ironstone.shared.ChatterServices.clean#Html').parameter('html', String(html)).call()?.html || ''
    } catch (err) {
        ec.logger.warn(`Chatter of ${entityName} ${recordId}: a body could not be cleaned, shown as text: ${err}`)
        return textHtml(plain(html))
    }
}
// mentions read as names; the class is added after the cleaning, which keeps only data-mention-id on a span
const mentionClass = (html) => html.replace(/<span data-mention-id="/g, '<span class="text-primary text-weight-medium" data-mention-id="')
// the body and its quoted text (an email's reply chain) apart
const bodyParts = (body, contentType) => {
    if (body == null || String(body).trim() === '') return {bodyHtml: null, quotedHtml: null, text: ''}
    const text = String(body)
    const isHtml = /html/i.test(contentType || '') || (!contentType && /<\/?(p|br|div|span|strong|em|ul|ol|li|a|blockquote|table)\b/i.test(text))
    if (isHtml) {
        const cleaned = clean(text)
        let at = cleaned.search(/<blockquote/i)
        if (at > 0) {
            const lead = cleaned.substring(Math.max(0, at - 300), at).search(/On [^<>]{4,200}wrote:/)
            if (lead >= 0) at = Math.max(0, at - 300) + lead
        }
        if (at > 0) {
            const head = clean(cleaned.substring(0, at))
            if (plain(head)) return {bodyHtml: mentionClass(head), quotedHtml: mentionClass(clean(cleaned.substring(at))), text: plain(cleaned)}
        }
        return {bodyHtml: mentionClass(cleaned), quotedHtml: null, text: plain(cleaned)}
    }
    const lines = text.split(/\r?\n/)
    const quoteAt = lines.findIndex((line, index) => index > 0 && (/^\s*>/.test(line) || /^On .{4,200}wrote:\s*$/.test(line)
            || /^-{2,}\s*Original Message\s*-{2,}/i.test(line)))
    if (quoteAt > 0) return {bodyHtml: textHtml(lines.slice(0, quoteAt).join('\n')), quotedHtml: textHtml(lines.slice(quoteAt).join('\n')), text: text}
    return {bodyHtml: textHtml(text), quotedHtml: null, text: text}
}

const entries = Array.from(out.entryList || [])
// the names of the authors and recipients, under the user's filters (a hidden contact is "Someone")
const partyIds = Array.from(new Set(entries.flatMap((entry) => [entry.authorPartyId, entry.toPartyId]).filter((id) => id)))
const names = {}
if (partyIds.length) for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', partyIds).list()) {
    // a personal contact of another user is not named (it shows as Someone)
    if (party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId) continue
    names[party.partyId] = (ec.resource.expand('PartyNameOnlyTemplate', '', party) || '').trim() || party.partyId
}
// the authors with a face image (the avatar transition shows it, checking the party again)
const faceIds = new Set(ec.service.sync().name('ironstone.shared.ChatterServices.get#FaceImageParties')
        .parameter('partyIdList', Object.keys(names)).call()?.partyIdList || [])
const userNames = {}
const userName = (userId) => {
    if (!userId) return null
    if (userNames[userId] === undefined) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one()
        userNames[userId] = account ? (account.userFullName || account.username) : null
    }
    return userNames[userId]
}
const statusText = {}
const statusOf = (statusId) => {
    if (!statusId) return null
    if (statusText[statusId] === undefined) {
        const status = ec.entity.find('moqui.basic.StatusItem').condition('statusId', statusId).useCache(true).one()
        statusText[statusId] = status ? status.description : statusId
    }
    return statusText[statusId]
}
const myPartyId = ec.user.userAccount?.partyId || null
// a client contact (impl-projects.md P10b) replies to a message for it, and nothing else: no unlink, no Inbox thread, no chat room
const forClient = !!recordOut.isClient
const mayUpdate = !forClient && ec.artifactExecution.isPermitted(entityName, 'AT_ENTITY', 'update')
const canMessage = forClient ? !!ec.service.sync().name('ironstone.client.ClientServices.get#ClientRecordWrites')
        .parameters({recordEntityName: entityName, recordId: recordId}).call()?.canMessage
    : ec.artifactExecution.isPermitted('mantle.party.communication.CommunicationEvent', 'AT_ENTITY', 'create')
const isAdmin = !forClient && !!ec.user.userId && ec.user.isInGroup('ADMIN')
// the notes of this page that have replies, which are not deleted until their replies are
const noteIds = entries.filter((entry) => entry.communicationEventId && entry.communicationEventTypeId === 'Comment')
        .map((entry) => entry.communicationEventId)
const repliedIds = new Set()
if (noteIds.length) {
    const cf = ec.entity.conditionFactory
    for (const reply of ec.entity.find('mantle.party.communication.CommunicationEvent').condition(cf.makeCondition([
            cf.makeCondition('parentCommEventId', 'in', noteIds), cf.makeCondition('rootCommEventId', 'in', noteIds)], 'or'))
            .selectField('communicationEventId').selectField('parentCommEventId').selectField('rootCommEventId').list()) {
        for (const id of [reply.parentCommEventId, reply.rootCommEventId]) if (id && id !== reply.communicationEventId) repliedIds.add(id)
    }
}
const messageTypes = {Email: ['sym_o_mail', 'info', 'Email'], Message: ['sym_o_chat', 'primary', 'Message'],
    Phone: ['sym_o_call', 'secondary', 'Phone call'], Call: ['sym_o_videocam', 'secondary', 'Call'],
    FaceToFace: ['sym_o_groups', 'secondary', 'Meeting'], Letter: ['sym_o_markunread_mailbox', 'info', 'Letter'],
    WebSiteVisit: ['sym_o_language', 'info', 'Web visit'], Fax: ['sym_o_fax', 'info', 'Fax']}
const purposes = {WepPhoneCall: ['sym_o_call', 'Call done'], WepEmail: ['sym_o_mail', 'Email done'], WepToDo: ['sym_o_checklist', 'To-do done'],
    WepMeeting: ['sym_o_groups', 'Meeting held']}
const statusColors = {CeBounced: 'negative', CeCancelled: 'negative', CeSent: 'info', CeReceived: 'info', CeViewed: 'info',
    CeInProgress: 'grey-7', CeReady: 'grey-7', CeResolved: 'positive'}
const fieldLabel = (fieldName) => {
    const base = String(fieldName || '').replace(/(Enum)?Id$/, '')
    const words = base.replace(/([a-z0-9])([A-Z])/g, '$1 $2').toLowerCase()
    return L(words.charAt(0).toUpperCase() + words.substring(1))
}
const keyOf = (map) => {
    const key = {}
    for (const [field, value] of Object.entries(map || {})) key[field] = /Date$/.test(field) ? toMillis(value) : (value == null ? null : String(value))
    return JSON.stringify(key)
}

// the cursor of the next page (get#RecordTimeline's), else the oldest entry of this one
nextBeforeDate = toMillis(out.nextBeforeDate)
for (const entry of entries) {
    const dateMillis = toMillis(entry.date)
    if (out.nextBeforeDate == null && dateMillis != null && (nextBeforeDate == null || dateMillis < nextBeforeDate)) nextBeforeDate = dateMillis
    // a field set when the record was made is no change, except its status ("Set to Submitted")
    const isStatus = /statusId$/i.test(entry.fieldName || '')
    if (entry.kind === 'change' && (entry.oldValue == null || entry.oldValue === '') && !isStatus) continue
    const authorName = names[entry.authorPartyId] || userName(entry.authorUserId) || null
    const decorated = {kind: entry.kind, dateMillis: dateMillis, dateText: whenText(dateMillis),
        dateFull: dateMillis == null ? '' : fmt(dateMillis, 'yyyy-MM-dd HH:mm'), authorPartyId: entry.authorPartyId || null,
        authorName: authorName, isMine: !!myPartyId && entry.authorPartyId === myPartyId, title: entry.title || null,
        authorImage: !!entry.authorPartyId && faceIds.has(entry.authorPartyId),
        bodyHtml: null, quotedHtml: null, status: null, attachments: [], canReply: false, emailReply: false, canUnlink: false,
        threadUrl: null, toName: null, edited: false, editedText: null, canEdit: false, canDelete: false, editBody: null}
    let searchText = [authorName, entry.title].filter((part) => part).join(' ')
    if (entry.kind === 'message' || (entry.kind === 'note' && entry.communicationEventId)) {
        const type = entry.communicationEventTypeId
        const typeInfo = entry.kind === 'note' ? ['sym_o_sticky_note_2', 'grey-7', 'Note'] : (messageTypes[type] || ['sym_o_forum', 'info', type || 'Message'])
        const parts = bodyParts(entry.body, entry.contentType)
        Object.assign(decorated, {key: 'ce-' + entry.communicationEventId, icon: typeInfo[0], color: typeInfo[1], kindLabel: L(typeInfo[2]),
            communicationEventId: entry.communicationEventId, communicationEventTypeId: type, bodyHtml: parts.bodyHtml, quotedHtml: parts.quotedHtml,
            toName: entry.kind === 'message' && entry.toPartyId && entry.toPartyId !== entry.authorPartyId ? (names[entry.toPartyId] || null) : null,
            parentCommEventId: entry.parentCommEventId || null,
            canReply: canMessage && (forClient ? (type === 'Message' || type === 'StatusUpdate') : (type === 'Message' || type === 'Comment')),
            emailReply: !forClient && type === 'Email',
            canUnlink: !forClient && (!!myPartyId && entry.fromPartyId === myPartyId || mayUpdate),
            threadUrl: !forClient && entry.kind === 'message' ? '/qapps/Comms/Inbox/MessageDetail?communicationEventId=' +
                encodeURIComponent(entry.rootCommEventId || entry.communicationEventId) : null})
        if (type === 'Email' && entry.statusId) decorated.status = {label: statusOf(entry.statusId), color: statusColors[entry.statusId] || 'grey-7'}
        // a note's author changes it, and its author or the ADMIN group deletes it while it has no replies
        const isNote = type === 'Comment'
        const mine = !!myPartyId && entry.fromPartyId === myPartyId
        const editedMillis = toMillis(entry.editedDate)
        decorated.edited = editedMillis != null
        decorated.editedText = editedMillis != null ? ec.resource.expand('Edited ${when}', '', {when: fmt(editedMillis, 'yyyy-MM-dd HH:mm')}) : null
        decorated.canEdit = !forClient && isNote && mine && canMessage
        decorated.canDelete = !forClient && isNote && (mine || isAdmin) && !repliedIds.has(entry.communicationEventId)
        const bodyIsHtml = /html/i.test(entry.contentType || '') || (!entry.contentType && /<\/?(p|br|div|span|strong|em|ul|ol|li|a|blockquote)\b/i.test(String(entry.body || '')))
        decorated.editBody = decorated.canEdit && entry.body != null ? (bodyIsHtml ? clean(String(entry.body)) : '<p>' + textHtml(String(entry.body)) + '</p>') : null
        decorated.attachments = Array.from(entry.attachments || []).filter((item) => item.contentLocation)
                .map((item) => ({id: item.communicationEventContentId, name: item.fileName || L('attachment')}))
        searchText += ' ' + parts.text
    } else if (entry.kind === 'note') {
        // a *Note row of the record (PartyNote, WorkEffortNote, RequestNote, OrderNote, FacilityNote)
        const parts = bodyParts(entry.body, 'text/plain')
        Object.assign(decorated, {key: 'note-' + entry.source + '-' + toMillis(entry.noteDate), icon: 'sym_o_sticky_note_2', color: 'grey-7',
            kindLabel: L('Note'), bodyHtml: parts.bodyHtml, quotedHtml: parts.quotedHtml})
        searchText += ' ' + parts.text
    } else if (entry.kind === 'activity') {
        const purpose = purposes[entry.purposeEnumId] || ['sym_o_task_alt', 'Activity done']
        const parts = bodyParts(entry.body, 'text/plain')
        const link = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters({docType: 'MantleWorkEffort',
            id: entry.workEffortId}).call()
        Object.assign(decorated, {key: 'we-' + entry.workEffortId, icon: purpose[0], color: 'positive', kindLabel: L(purpose[1]),
            workEffortId: entry.workEffortId, url: link?.url || null, bodyHtml: parts.bodyHtml})
        searchText += ' ' + parts.text
    } else if (entry.kind === 'change') {
        const from = entry.oldValueDescription ?? entry.oldValue ?? ''
        const to = entry.newValueDescription ?? entry.newValue ?? ''
        Object.assign(decorated, {key: 'audit-' + entry.auditHistorySeqId, icon: 'sym_o_history', color: 'grey-6', kindLabel: L('Change'),
            title: fieldLabel(entry.fieldName), bodyHtml: (from ? escapeHtml(from) + ' → ' + escapeHtml(to || '–')
                : ec.resource.expand('Set to ${value}', '', {value: escapeHtml(to || '–')})) +
                (entry.changeReason ? '<br>' + textHtml(entry.changeReason) : '')})
        searchText += ' ' + from + ' ' + to
    } else if (entry.kind === 'file') {
        const parts = bodyParts(entry.body, 'text/plain')
        const name = entry.title || L('A file')
        Object.assign(decorated, {key: 'file-' + keyOf(entry.contentKey), icon: 'sym_o_attach_file', color: 'secondary', kindLabel: L('File added'),
            title: name, contentKey: keyOf(entry.contentKey), isImage: /\.(png|jpe?g|gif|webp)$/i.test(name), isPdf: /\.pdf$/i.test(name),
            bodyHtml: parts.bodyHtml})
        searchText += ' ' + parts.text
    } else if (entry.kind === 'chat') {
        // a message of the record's chat room (get#RecordTimeline gives its room and url): Open goes to it in Chat
        const parts = bodyParts(entry.body || entry.bodyText, entry.body ? 'text/html' : 'text/plain')
        Object.assign(decorated, {key: 'chat-' + entry.chatRoomId + '-' + entry.eventSeq, icon: 'sym_o_chat', color: 'primary', kindLabel: L('Chat'),
            authorName: authorName || entry.authorName || null, title: null, bodyHtml: parts.bodyHtml,
            url: forClient ? null : (entry.url || ('/qapps/Comms/Chat?chatRoomId=' + encodeURIComponent(entry.chatRoomId) + '&eventSeq=' + entry.eventSeq)),
            toName: entry.roomName || null})
        searchText += ' ' + parts.text + ' ' + (entry.authorName || '')
    } else if (entry.kind === 'time') {
        // time logged on a work item (mantle.work.TimeServices.get#TimeEntryTimeline): who, how long, the work type and
        // the comment, never a rate (impl-projects.md P6b)
        const parts = bodyParts(entry.body, 'text/plain')
        const span = entry.fromDate != null && entry.thruDate != null ? fmt(toMillis(entry.fromDate), 'MMM d, HH:mm') + '–' + fmt(toMillis(entry.thruDate), 'HH:mm') : ''
        Object.assign(decorated, {key: 'time-' + entry.timeEntryId, icon: 'sym_o_schedule', color: 'teal', kindLabel: L('Time logged'),
            title: entry.title + (entry.billable === false ? ' · ' + L('not billable') : '') + (span ? ' · ' + span : ''), bodyHtml: parts.bodyHtml})
        searchText += ' ' + parts.text
    } else {
        // a registered source's entry
        const parts = bodyParts(entry.body, entry.contentType)
        Object.assign(decorated, {key: 'src-' + entry.source + '-' + dateMillis + '-' + entryList.length, icon: 'sym_o_forum', color: 'info',
            kindLabel: L(String(entry.kind || 'Entry')), bodyHtml: parts.bodyHtml})
        searchText += ' ' + parts.text
    }
    decorated.searchText = searchText.toLowerCase()
    entryList.push(decorated)
}

service-call.in-map:
{recordEntityName:recordOut.info.recordEntityName,
                    recordId:recordId, subject:subject, body:body, contentType:'text/html', parentCommEventId:parentCommEventId,
                    mentionUserIds:mentionsOut.userIdList, recordUrl:urlOut.recordUrl}

actions.script:
const notOnRecord = () => ec.message.addError(ec.resource.expand('Message ${id} is not on this record', '', {id: communicationEventId}))
const value = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
if (value == null) { notOnRecord(); return }
// a note or message filed on a confidential case is its people's alone (impl-people P21 review): on no other record for
// anyone else, its author's or a recipient's party included (an attachment, a reply, taking it off)
if (ec.resource.script('component://mr-mantle/service/mantle/request/PeopleCases.js').hiddenEventIds([communicationEventId]).length) {
    notOnRecord(); return }
const found = (entityName, keys) => ec.entity.find(entityName).condition(keys).count() > 0
let on = false
if (info.isParty) {
    on = value.fromPartyId === recordId || value.toPartyId === recordId ||
            found('mantle.party.communication.CommunicationEventParty', {communicationEventId: communicationEventId, partyId: recordId})
} else {
    for (const id of [value.communicationEventId, value.rootCommEventId].filter((item) => item)) {
        if (info.commEventJoin && found(info.commEventJoin.entityName, {communicationEventId: id, [info.commEventJoin.keyField]: recordId})) on = true
        if (!on && found('mantle.party.communication.CommunicationEventRecord', {communicationEventId: id,
                recordEntityName: info.recordEntityName, recordId: recordId})) on = true
        if (on) break
    }
}
if (!on) { notOnRecord(); return }
commEvent = value.getMap()

service-call.in-map:
{parentCommEventId:parentCommEventId,
                    subject:(parentSubject ? (parentSubject.startsWith('Re: ') ? parentSubject : 'Re: ' + parentSubject) : null), body:body,
                    contentType:'text/html', mentionPartyIdList:mentionsOut.partyIdList}

service.description:
Takes a message or note off the record (mantle.party.CommunicationServices.unlink#CommunicationEventRecord);
            the event itself stays. Its sender may, or a user the record's authorization lets update the record. A party the
            event is from or to, or a recipient of, stays linked.

actions.script:
contentLocation = String(eventContent.contentLocation)
const last = contentLocation.substring(contentLocation.lastIndexOf('/') + 1)
try { fileName = decodeURIComponent(last) } catch (err) { fileName = last }
inlineAllowed = /\.(png|jpe?g|gif|webp|pdf)$/i.test(fileName)

service-call.in-map:
{activityType:activityType,
                    workEffortName:workEffortName, dueDate:dueDate, endDate:endDate, assignToPartyId:(assignToPartyId || ec.user.userAccount?.partyId),
                    description:description, recordEntity:recordOut.info.recordEntityName, recordId:recordId, recordUrl:urlOut.recordUrl}

actions.script:
const cf = ec.entity.conditionFactory
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
const joined = row != null && ((info.workEffortJoin && ec.entity.find(info.workEffortJoin.entityName)
        .condition({workEffortId: workEffortId, [info.workEffortJoin.keyField]: recordId}).count() > 0) ||
        ec.entity.find('mantle.work.effort.WorkEffortRecord').condition({workEffortId: workEffortId,
            recordEntityName: info.recordEntityName, recordId: recordId}).count() > 0)
if (!joined) { ec.message.addError(ec.resource.expand('Activity ${workEffortId} is not on this record', '', {workEffortId: workEffortId})); return }
const partyId = ec.user.userAccount?.partyId
const mine = !!partyId && (row.ownerPartyId === partyId || ec.entity.find('mantle.work.effort.WorkEffortParty')
        .condition('workEffortId', workEffortId).condition('partyId', partyId).condition('roleTypeId', 'Assignee')
        .condition(cf.makeConditionDate('fromDate', 'thruDate', ec.user.nowTimestamp))
        .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).count() > 0)
if (!mine) { ec.message.addError(ec.resource.expand('You may not change activity ${name}', '', {name: row.workEffortName || workEffortId})); return }
workEffort = row.getMap()

service-call.in-map:
{recordEntityName:recordEntityName, recordId:recordId,
                        body:feedback, recordUrl:recordUrl, subject:ec.resource.expand('${kind} done: ${name}', '',
                            {kind:ec.l10n.localize(purposeLabels[checked.workEffort.purposeEnumId] || 'Activity'), name:activityName})}

actions.script:
updateFields = {workEffortId: workEffortId, workEffortName: workEffortName, description: description || null}
if (checked.workEffort.purposeEnumId === 'WepMeeting' || checked.workEffort.workEffortTypeEnumId === 'WetEvent') {
    if (dueDate != null) {
        const startMillis = Number(String(dueDate))
        updateFields.estimatedStartDate = dueDate
        updateFields.estimatedCompletionDate = endDate != null && Number(String(endDate)) > startMillis ? endDate : new Date(startMillis + 1800000)
    }
} else if (dueDate != null) updateFields.estimatedCompletionDate = dueDate

addedUserIds = []
const added = []
usersOut.userIdList.forEach((followerUserId, index) => {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('mantle.party.CommunicationServices.follow#Record').parameters({recordEntityName: recordOut.info.recordEntityName,
            recordId: recordId, userId: followerUserId}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        addedUserIds.push(followerUserId)
        added.push(usersOut.nameList[index])
    } catch (err) {
        ec.logger.error(`Chatter of ${recordEntityName} ${recordId}: follower ${followerUserId} was not added: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
})
if (addedUserIds.length === 0) { ec.message.addError(ec.l10n.localize('No follower was added')); return }
message = ec.resource.expand('Following now: ${names}', '', {names: added.join(', ')})

const L = (text) => ec.l10n.localize(text)
const entityName = recordOut.info.recordEntityName
const keys = {'mantle.party.Party': 'party', 'mantle.request.Request': 'request', 'mantle.work.effort.WorkEffort': 'workEffort',
    'mantle.order.OrderHeader': 'orderHeader', 'mantle.account.invoice.Invoice': 'invoice', 'mantle.account.payment.Payment': 'payment',
    'mantle.shipment.Shipment': 'shipment', 'mantle.product.Product': 'product', 'mantle.product.asset.Asset': 'asset',
    'mantle.facility.Facility': 'facility', 'mantle.party.communication.CommunicationEvent': 'communicationEvent',
    'mantle.order.return.ReturnHeader': 'returnHeader', 'mantle.product.asset.Container': 'container'}
const row = Object.assign({}, recordOut.record, (keys[entityName] && found[keys[entityName]]) || {})
const enumText = (enumId) => {
    if (!enumId) return ''
    const item = ec.entity.find('moqui.basic.Enumeration').condition('enumId', enumId).useCache(true).one()
    return item ? (item.description || enumId) : enumId
}
const dateText = (value) => value == null || value === '' ? '' : ec.l10n.format(new Date(Number(String(value))), 'yyyy-MM-dd')
// the color of a status by its meaning (style-guide §5.2)
const colorOf = (statusId) => {
    const id = String(statusId)
    if (/(Cancel|Reject|Void|Lost|Fail|Bounce|Declin)/.test(id)) return 'negative'
    if (/(Complete|Paid|Shipped|Deliver|Won|Resolved|Closed|Finali)/.test(id)) return 'positive'
    if (/(Hold|Pending|Overdue|Backorder|Wait)/.test(id)) return 'warning'
    if (/(Sent|Received|Viewed|Scheduled|Invoiced|Submitted)/.test(id)) return 'info'
    if (/(Approved|Progress|Open|Active|Picking|Assigned|Placed|Processing)/.test(id)) return 'primary'
    return 'grey-7'
}
let status = null
if (row.statusId) {
    const item = ec.entity.find('moqui.basic.StatusItem').condition('statusId', row.statusId).useCache(true).one()
    status = {label: item ? item.description : row.statusId, color: colorOf(row.statusId)}
}
const fields = []
if (entityName === 'mantle.request.Request') {
    fields.push({label: L('Type'), value: enumText(row.requestTypeEnumId)}, {label: L('Priority'), value: row.priority ?? ''})
} else if (entityName === 'mantle.work.effort.WorkEffort') {
    if (row.workEffortTypeEnumId === 'WetEvent') fields.push({label: L('Starts'), value: dateText(row.estimatedStartDate)})
    else fields.push({label: L('Due'), value: dateText(row.estimatedCompletionDate)})
    fields.push({label: L('Purpose'), value: enumText(row.purposeEnumId)})
} else if (entityName === 'mantle.party.Party') {
    fields.push({label: L('Id'), value: row.pseudoId || ''})
} else if (entityName === 'mantle.order.OrderHeader') {
    fields.push({label: L('Total'), value: row.grandTotal != null ? ec.l10n.formatCurrency(row.grandTotal, row.currencyUomId || 'USD') : ''})
} else if (entityName === 'mantle.account.invoice.Invoice') {
    fields.push({label: L('Total'), value: row.invoiceTotal != null ? ec.l10n.formatCurrency(row.invoiceTotal, row.currencyUomId || 'USD') : ''},
        {label: L('Due'), value: dateText(row.dueDate)})
}
card = {title: recordOut.title, typeLabel: recordOut.typeLabel, icon: recordOut.icon, id: recordId, entity: entityName,
    url: recordOut.url, status: status, fields: fields.filter((field) => field.value !== '' && field.value != null)
        .map((field) => ({label: field.label, value: String(field.value)}))}
